   335  /**************************************/
   336
   337  static exr_result_t
   338  extract_attr_chlist (
   339      struct _internal_exr_context*     ctxt,
   340      struct _internal_exr_seq_scratch* scratch,
   341      exr_attr_chlist_t*                attrdata,
   342      const char*                       aname,
   343      const char*                       tname,
   344      int32_t                           attrsz)
   345  {
   346      char         chname[256];
   347      int32_t      chlen;
   348      int32_t      ptype, xsamp, ysamp;
   349      uint8_t      flags[4];
   350      int32_t      maxlen = ctxt->max_name_length;
   351      exr_result_t rv;
   352
   353      rv = check_bad_attrsz (ctxt, scratch, attrsz, 1, aname, tname, &chlen);
   354
   355      while (rv == EXR_ERR_SUCCESS && attrsz > 0)
   356      {
   357          chlen = 0;
   358          rv    = read_text (ctxt, chname, &chlen, maxlen, scratch, aname);
   359          if (rv != EXR_ERR_SUCCESS) break;
   360          attrsz -= chlen + 1;
   361
   362          if (chlen == 0) break;
   363
   364          if (attrsz < 16)
   365          {
   366              return ctxt->print_error (
   367                  ctxt,
   368                  EXR_ERR_ATTR_SIZE_MISMATCH,
   369                  "Out of data parsing '%s', last channel '%s'",
   370                  aname,
   371                  chname);
   372          }
   373
   374          rv = scratch->sequential_read (scratch, &ptype, 4);
   375          if (rv != EXR_ERR_SUCCESS) break;
   376          rv = scratch->sequential_read (scratch, &flags, 4);
   377          if (rv != EXR_ERR_SUCCESS) break;
   378          rv = scratch->sequential_read (scratch, &xsamp, 4);
   379          if (rv != EXR_ERR_SUCCESS) break;
   380          rv = scratch->sequential_read (scratch, &ysamp, 4);
   381          if (rv != EXR_ERR_SUCCESS) break;
   382
   383          attrsz -= 16;
   384          ptype = (int32_t) one_to_native32 ((uint32_t) ptype);
   385          xsamp = (int32_t) one_to_native32 ((uint32_t) xsamp);
   386          ysamp = (int32_t) one_to_native32 ((uint32_t) ysamp);
   387
   388          rv = exr_attr_chlist_add_with_length (
   389              (exr_context_t) ctxt,
   390              attrdata,
   391              chname,
   392              chlen,
   393              (exr_pixel_type_t) ptype,
   394              flags[0],
   395              xsamp,
   396              ysamp);
   397      }
   398      return rv;
   399  }
   400
   401  /**************************************/
   402
   403  static exr_result_t
   404  extract_attr_uint8 (
   405      struct _internal_exr_context*     ctxt,
   406      struct _internal_exr_seq_scratch* scratch,
   407      uint8_t*                          attrdata,
   408      const char*                       aname,
   409      const char*                       tname,
   410      int32_t                           attrsz,
  1840          case 'v':
  1841              if (0 == strcmp (aname, EXR_REQ_VERSION_STR))
  1842                  return check_populate_version (
  1843                      ctxt, curpart, scratch, tname, attrsz);
  1844              break;
  1845          default: break;
  1846      }
  1847
  1848      return EXR_ERR_UNKNOWN;
  1849  }
  1850
  1851  /**************************************/
  1852
  1853  static exr_result_t
  1854  pull_attr (
  1855      struct _internal_exr_context*     ctxt,
  1856      struct _internal_exr_part*        curpart,
  1857      uint8_t                           init_byte,
  1858      struct _internal_exr_seq_scratch* scratch)
  1859  {
  1860      char             name[256], type[256];
  1861      exr_result_t     rv;
  1862      int32_t          namelen = 0, typelen = 0;
  1863      int32_t          attrsz = 0;
  1864      exr_attribute_t* nattr  = NULL;
  1865      uint8_t*         strptr = NULL;
  1866      const int32_t    maxlen = ctxt->max_name_length;
  1867
  1868      name[0] = (char) init_byte;
  1869      namelen = 1;
  1870
  1871      rv = read_text (ctxt, name, &namelen, maxlen, scratch, "attribute name");
  1872      if (rv != EXR_ERR_SUCCESS) return rv;
  1873      rv = read_text (ctxt, type, &typelen, maxlen, scratch, "attribute type");
  1874      if (rv != EXR_ERR_SUCCESS) return rv;
  1875
  1876      if (namelen == 0)
  1877          return ctxt->report_error (
  1878              ctxt,
  1879              EXR_ERR_FILE_BAD_HEADER,
  1880              "Invalid empty string encountered parsing attribute name");
  1881
  1882      if (typelen == 0)
  1883          return ctxt->print_error (
  1884              ctxt,
  1885              EXR_ERR_FILE_BAD_HEADER,
  1886              "Invalid empty string encountered parsing attribute type for attribute '%s'",
  1887              name);
  1888
  1889      rv = scratch->sequential_read (scratch, &attrsz, sizeof (int32_t));
  1890      if (rv != EXR_ERR_SUCCESS)
  1891          return ctxt->print_error (
  1892              ctxt,
  1893              rv,
  1894              "Unable to read attribute size for attribute '%s', type '%s'",
  1895              name,
  1896              type);
  1897      attrsz = (int32_t) one_to_native32 ((uint32_t) attrsz);
  1898
  1899      rv = check_req_attr (ctxt, curpart, scratch, name, type, attrsz);
  1900      if (rv != EXR_ERR_UNKNOWN) return rv;
  1901
  1902      /* not a required attr, just a normal one, optimize for string type to avoid double malloc */
  1903      if (!strcmp (type, "string"))
  1904      {
  1905          int32_t n;
  1906          rv = check_bad_attrsz (ctxt, scratch, attrsz, 1, name, type, &n);
  1907          if (rv != EXR_ERR_SUCCESS) return rv;
  1908
  1909          rv = exr_attr_list_add (
  1910              (exr_context_t) ctxt,
  1911              &(curpart->attributes),
  1912              name,
  1913              EXR_ATTR_STRING,
  1914              n + 1,
  1915              &strptr,
  1916              &nattr);
  1917      }
  1918      else
  1919      {
  1920          rv = exr_attr_list_add_by_type (
  1921              (exr_context_t) ctxt,
  1922              &(curpart->attributes),
  1923              name,
  1924              type,
  1925              0,
  1926              NULL,
  1927              &nattr);
  1928      }
  1929
  1930      if (rv != EXR_ERR_SUCCESS)
  1931          return ctxt->print_error (
  1932              ctxt,
  1933              rv,
  1934              "Unable to initialize attribute '%s', type '%s'",
  1935              name,
  1936              type);
  1937
  1938      switch (nattr->type)
  1939      {
  1940          case EXR_ATTR_BOX2I:
  1941              rv = extract_attr_32bit (
  1942                  ctxt, scratch, nattr->box2i, name, type, attrsz, 4);
  1943              break;
  1944          case EXR_ATTR_BOX2F:
  1945              rv = extract_attr_32bit (
  1946                  ctxt, scratch, nattr->box2f, name, type, attrsz, 4);
  1947              break;
  1948          case EXR_ATTR_CHLIST:
  1949              rv = extract_attr_chlist (
  1950                  ctxt, scratch, nattr->chlist, name, type, attrsz);
  1951              break;
  1952          case EXR_ATTR_CHROMATICITIES:
  1953              rv = extract_attr_32bit (
  1954                  ctxt, scratch, nattr->chromaticities, name, type, attrsz, 8);
  1955              break;
  1956          case EXR_ATTR_COMPRESSION:
  1957              rv = extract_attr_uint8 (
  1958                  ctxt,
  1959                  scratch,
  1960                  &(nattr->uc),
  1961                  name,
  1962                  type,
  1963                  attrsz,
  1964                  (uint8_t) EXR_COMPRESSION_LAST_TYPE);
  1965              break;
  1966          case EXR_ATTR_ENVMAP:
  1967              rv = extract_attr_uint8 (
  1968                  ctxt,
  1969                  scratch,
  1970                  &(nattr->uc),
  1971                  name,
  1972                  type,
  1973                  attrsz,
  1974                  (uint8_t) EXR_ENVMAP_LAST_TYPE);
  1975              break;
  1976          case EXR_ATTR_LINEORDER:
  1977              rv = extract_attr_uint8 (
  1978                  ctxt,
  1979                  scratch,
  1980                  &(nattr->uc),
  1981                  name,
  1982                  type,
  1983                  attrsz,
  1984                  (uint8_t) EXR_LINEORDER_LAST_TYPE);
  1985              break;
